def f(g):
    g=[r[:] for r in g]; H=len(g); W=len(g[0]); out=[r[:] for r in g]
    seen=[[False]*W for _ in range(H)]
    def collect(i,j,c):
        stack=[(i,j)]; seen[i][j]=True; res=[]
        while stack:
            a,b=stack.pop(); res.append((a,b))
            for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                x,y=a+da,b+db
                if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==c:
                    seen[x][y]=True; stack.append((x,y))
        return res
    comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and not seen[i][j]:
                comps.append(collect(i,j,g[i][j]))
    marks=set()  # (kind,idx,color) -> whether painted
    lines=[]     # list of (kind,idx,color)
    for comp in comps:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        h=r1-r0+1; w=c1-c0+1
        c=g[r0][c0]
        if h>w:  # tall: full column
            lines.append(('col',(c0+c1)//2,c))
        elif w>h: # wide: full row
            lines.append(('row',(r0+r1)//2,c))
        else:     # square-ish: both
            lines.append(('col',(c0+c1)//2,c))
            lines.append(('row',(r0+r1)//2,c))
    # resolve conflicts: a cell claimed by two different colors -> 0
    claim={};  # (r,c)->set of colors
    for kind,idx,col in lines:
        for r in range(H):
            for c2 in range(W):
                if (kind=='col' and c2==idx) or (kind=='row' and r==idx):
                    claim.setdefault((r,c2),set()).add(col)
    res=[r[:] for r in g]
    for (r,c2),cols in claim.items():
        if len(cols)>1: continue
        col=next(iter(cols))
        if kind=='col':
            for rr in range(H): res[rr][c2]=col
        else:
            for cc in range(W): res[r][cc]=col
    return res

