import numpy as np
def cc(g):
    g=np.array(g); H,W=g.shape; seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if int(g[i,j])==0 or (i,j) in seen: continue
            st=[(i,j)]; cs=[]
            while st:
                a,b=st.pop()
                if int(g[a,b])==0 or (a,b) in seen: continue
                seen.add((a,b)); cs.append((a,b))
                for dx in(-1,0,1):
                    for dy in(-1,0,1):
                        x,y=a+dx,b+dy
                        if 0<=x<H and 0<=y<W and int(g[x,y])!=0 and (x,y) not in seen: st.append((x,y))
            r0=min(p[0] for p in cs); c0=min(p[1] for p in cs)
            r1=max(p[0] for p in cs); c1=max(p[1] for p in cs)
            out.append({'v':int(g[i,j]),'n':len(cs),'r0c0':(r0,c0),'r1c1':(r1,c1),
                        'solid':(r1-r0+1)*(c1-c0+1)==len(cs)})
    return out
